# PowerShell 5+
Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

$projectRoot = Get-Location
$tempRoot = Join-Path $env:TEMP "slot_precision_apply_20260401"
New-Item -ItemType Directory -Force -Path $tempRoot | Out-Null

function Write-Base64Zip {
    param(
        [string]$Name,
        [string]$Base64
    )
    $zipPath = Join-Path $tempRoot ("$Name.zip")
    [IO.File]::WriteAllBytes($zipPath, [Convert]::FromBase64String($Base64))
    return $zipPath
}

function Expand-ToProject {
    param(
        [string]$ZipPath
    )
    $extractDir = Join-Path $tempRoot ([IO.Path]::GetFileNameWithoutExtension($ZipPath))
    if (Test-Path $extractDir) { Remove-Item -Recurse -Force $extractDir }
    Expand-Archive -Path $ZipPath -DestinationPath $extractDir -Force
    $candidateRoots = @(
        $extractDir,
        (Join-Path $extractDir "diff_precision_batch_2026-04-01"),
        (Join-Path $extractDir "precision_priority_batch_2026-04-01-d")
    ) | Where-Object { Test-Path $_ }
    foreach ($root in $candidateRoots) {
        $appPath = Join-Path $root "app"
        $docsPath = Join-Path $root "docs"
        if (Test-Path $appPath) { Copy-Item -Recurse -Force (Join-Path $appPath "*") (Join-Path $projectRoot "app") }
        if (Test-Path $docsPath) {
            $destDocs = Join-Path $projectRoot "docs"
            New-Item -ItemType Directory -Force -Path $destDocs | Out-Null
            Copy-Item -Recurse -Force (Join-Path $docsPath "*") $destDocs
        }
    }
}

